package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="participantes_conversacion_interna",uniqueConstraints=@UniqueConstraint(columnNames={"cin_id","usu_id"}))
public class ParticipanteConversacionInterna{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="pci_id")private Long id;@Column(name="cin_id",nullable=false)private Long conversacionId;@Column(name="usu_id",nullable=false)private Long usuarioId;@Column(name="pci_fec_lei")private LocalDateTime fechaLectura;@Column(name="pci_act",nullable=false)private Boolean activa=true;public Long getId(){return id;}public Long getConversacionId(){return conversacionId;}public void setConversacionId(Long v){conversacionId=v;}public Long getUsuarioId(){return usuarioId;}public void setUsuarioId(Long v){usuarioId=v;}public LocalDateTime getFechaLectura(){return fechaLectura;}public void setFechaLectura(LocalDateTime v){fechaLectura=v;}public Boolean getActiva(){return activa;}public void setActiva(Boolean v){activa=v;}}
